import{_ as r,c as i,o as s,a2 as a}from"./chunks/framework.CIiVzG-O.js";const p=JSON.parse(`{"title":"Guide d'utilisation","description":"","frontmatter":{},"headers":[],"relativePath":"fr/guide/usage.md","filePath":"fr/guide/usage.md","lastUpdated":1793163976000}`),o={name:"fr/guide/usage.md"};function t(l,e,n,c,d,u){return s(),i("div",null,[...e[0]||(e[0]=[a('<h1 id="guide-d-utilisation" tabindex="-1">Guide d&#39;utilisation <a class="header-anchor" href="#guide-d-utilisation" aria-label="Permalink to &quot;Guide d&#39;utilisation&quot;">​</a></h1><h2 id="ouverture-d-archives" tabindex="-1">Ouverture d&#39;archives <a class="header-anchor" href="#ouverture-d-archives" aria-label="Permalink to &quot;Ouverture d&#39;archives&quot;">​</a></h2><h3 id="double-clic-pour-ouvrir" tabindex="-1">Double-clic pour ouvrir <a class="header-anchor" href="#double-clic-pour-ouvrir" aria-label="Permalink to &quot;Double-clic pour ouvrir&quot;">​</a></h3><p>NueZip s&#39;enregistre comme gestionnaire par défaut pour tous les formats d&#39;archives pris en charge. Il suffit de double-cliquer sur n&#39;importe quel fichier d&#39;archive (<code>.zip</code>, <code>.rar</code>, <code>.7z</code>, <code>.tar</code>, <code>.gz</code>, <code>.bz2</code>, <code>.xz</code>, <code>.zst</code>) pour l&#39;ouvrir dans la fenêtre principale de NueZip.</p><h3 id="ouvrir-avec-nuezip-menu-contextuel-finder" tabindex="-1">Ouvrir avec NueZip (menu contextuel Finder) <a class="header-anchor" href="#ouvrir-avec-nuezip-menu-contextuel-finder" aria-label="Permalink to &quot;Ouvrir avec NueZip (menu contextuel Finder)&quot;">​</a></h3><p>Faites un clic droit sur n&#39;importe quel fichier d&#39;archive et sélectionnez <strong>Ouvrir avec NueZip</strong> dans le menu contextuel. L&#39;extension Finder propose également des actions rapides :</p><ul><li><strong>Extraire ici</strong> — Extrait le contenu de l&#39;archive dans le dossier courant</li><li><strong>Extraire vers « NomDossier/ »</strong> — Extrait dans un sous-dossier nommé</li><li><strong>Compresser en ZIP</strong> — Compresse les fichiers/dossiers sélectionnés en une archive ZIP</li><li><strong>Ouvrir avec NueZip</strong> — Ouvre dans la fenêtre de navigation principale</li></ul><h3 id="glisser-deposer-vers-la-zone" tabindex="-1">Glisser-déposer vers la zone <a class="header-anchor" href="#glisser-deposer-vers-la-zone" aria-label="Permalink to &quot;Glisser-déposer vers la zone&quot;">​</a></h3><p>Glissez n&#39;importe quel fichier d&#39;archive sur l&#39;icône de la barre de menu de NueZip pour l&#39;ouvrir rapidement dans le panneau de dépôt pour un accès instantané. Vous pouvez également glisser des fichiers sur l&#39;icône de la zone pour les compresser.</p><h2 id="extraction-d-archives" tabindex="-1">Extraction d&#39;archives <a class="header-anchor" href="#extraction-d-archives" aria-label="Permalink to &quot;Extraction d&#39;archives&quot;">​</a></h2><h3 id="extraction-de-base" tabindex="-1">Extraction de base <a class="header-anchor" href="#extraction-de-base" aria-label="Permalink to &quot;Extraction de base&quot;">​</a></h3><ol><li>Ouvrez une archive dans NueZip</li><li>Cliquez sur le bouton <strong>Extraire</strong> dans la barre d&#39;outils</li><li>Choisissez un dossier de destination</li><li>Cliquez sur <strong>Extraire</strong></li></ol><h3 id="extraction-rapide-depuis-finder" tabindex="-1">Extraction rapide depuis Finder <a class="header-anchor" href="#extraction-rapide-depuis-finder" aria-label="Permalink to &quot;Extraction rapide depuis Finder&quot;">​</a></h3><p>Faites un clic droit sur une archive dans Finder et sélectionnez l&#39;une des actions rapides :</p><ul><li><strong>Extraire ici</strong> — Extrait directement dans le dossier courant</li><li><strong>Extraire vers « [NomArchive]/ »</strong> — Extrait dans un sous-dossier nommé pour un rangement propre</li></ul><h3 id="extraction-avec-mot-de-passe" tabindex="-1">Extraction avec mot de passe <a class="header-anchor" href="#extraction-avec-mot-de-passe" aria-label="Permalink to &quot;Extraction avec mot de passe&quot;">​</a></h3><p>Pour les archives protégées par mot de passe, NueZip vous demandera le mot de passe. Le gestionnaire de mots de passe intégré peut stocker les identifiants en toute sécurité dans votre trousseau local pour une utilisation ultérieure.</p><h2 id="compression-d-archives" tabindex="-1">Compression d&#39;archives <a class="header-anchor" href="#compression-d-archives" aria-label="Permalink to &quot;Compression d&#39;archives&quot;">​</a></h2><h3 id="creer-une-nouvelle-archive" tabindex="-1">Créer une nouvelle archive <a class="header-anchor" href="#creer-une-nouvelle-archive" aria-label="Permalink to &quot;Créer une nouvelle archive&quot;">​</a></h3><ol><li>Sélectionnez des fichiers ou dossiers dans la fenêtre principale de NueZip</li><li>Cliquez sur le bouton <strong>Compresser</strong> dans la barre d&#39;outils</li><li>Choisissez le format d&#39;archive (ZIP, 7z, TAR, GZIP, etc.)</li><li>Configurez les paramètres de compression (niveau, méthode de chiffrement)</li><li>Cliquez sur <strong>Compresser</strong></li></ol><h3 id="compresser-depuis-finder" tabindex="-1">Compresser depuis Finder <a class="header-anchor" href="#compresser-depuis-finder" aria-label="Permalink to &quot;Compresser depuis Finder&quot;">​</a></h3><p>Faites un clic droit sur des fichiers/dossiers dans Finder et sélectionnez <strong>Compresser avec NueZip</strong> :</p><ul><li><strong>Compresser en ZIP</strong> — Création rapide d&#39;une archive ZIP</li><li><strong>Compresser avec options</strong> — Ouvre NueZip avec les paramètres avancés</li></ul><h3 id="compresser-via-glisser-deposer" tabindex="-1">Compresser via glisser-déposer <a class="header-anchor" href="#compresser-via-glisser-deposer" aria-label="Permalink to &quot;Compresser via glisser-déposer&quot;">​</a></h3><p>Glissez des fichiers sur l&#39;icône de zone de la barre de menu de NueZip pour créer rapidement une archive ZIP.</p><h2 id="operations-par-lot" tabindex="-1">Opérations par lot <a class="header-anchor" href="#operations-par-lot" aria-label="Permalink to &quot;Opérations par lot&quot;">​</a></h2><h3 id="compression-par-lot" tabindex="-1">Compression par lot <a class="header-anchor" href="#compression-par-lot" aria-label="Permalink to &quot;Compression par lot&quot;">​</a></h3><ol><li>Sélectionnez plusieurs éléments dans NueZip</li><li>Choisissez <strong>Compression par lot</strong> depuis la barre d&#39;outils ou le menu Fichier</li><li>Chaque élément sera compressé dans une archive séparée</li></ol><h3 id="extraction-par-lot" tabindex="-1">Extraction par lot <a class="header-anchor" href="#extraction-par-lot" aria-label="Permalink to &quot;Extraction par lot&quot;">​</a></h3><ol><li>Sélectionnez plusieurs archives dans NueZip</li><li>Choisissez <strong>Extraction par lot</strong> depuis la barre d&#39;outils ou le menu Fichier</li><li>Toutes les archives seront extraites simultanément</li></ol><h3 id="conversion-par-lot" tabindex="-1">Conversion par lot <a class="header-anchor" href="#conversion-par-lot" aria-label="Permalink to &quot;Conversion par lot&quot;">​</a></h3><ol><li>Sélectionnez une ou plusieurs archives</li><li>Choisissez <strong>Convertir</strong> → sélectionnez le format cible</li><li>NueZip recompressera chaque archive dans le format choisi</li></ol><h3 id="chiffrement-par-lot" tabindex="-1">Chiffrement par lot <a class="header-anchor" href="#chiffrement-par-lot" aria-label="Permalink to &quot;Chiffrement par lot&quot;">​</a></h3><ol><li>Sélectionnez plusieurs archives ZIP</li><li>Choisissez <strong>Chiffrement par lot</strong></li><li>Définissez un mot de passe — toutes les archives sélectionnées seront protégées par mot de passe</li></ol><h2 id="conversion-de-format" tabindex="-1">Conversion de format <a class="header-anchor" href="#conversion-de-format" aria-label="Permalink to &quot;Conversion de format&quot;">​</a></h2><p>Convertissez des archives entre n&#39;importe quels formats pris en charge :</p><ol><li>Ouvrez une archive</li><li>Cliquez sur <strong>Convertir</strong> dans la barre d&#39;outils</li><li>Sélectionnez le format cible (par ex., RAR → ZIP, 7z → TAR.GZ)</li><li>Choisissez l&#39;emplacement de sortie</li><li>Cliquez sur <strong>Convertir</strong></li></ol><h2 id="reparation-d-archive" tabindex="-1">Réparation d&#39;archive <a class="header-anchor" href="#reparation-d-archive" aria-label="Permalink to &quot;Réparation d&#39;archive&quot;">​</a></h2><p>Pour les archives RAR ou ZIP corrompues :</p><ol><li>Ouvrez l&#39;archive corrompue</li><li>Cliquez sur <strong>Réparer</strong> dans la barre d&#39;outils</li><li>NueZip tentera de reconstruire les données de l&#39;archive</li><li>L&#39;archive réparée est enregistrée en tant que nouveau fichier</li></ol><h2 id="recherche-dans-les-archives" tabindex="-1">Recherche dans les archives <a class="header-anchor" href="#recherche-dans-les-archives" aria-label="Permalink to &quot;Recherche dans les archives&quot;">​</a></h2><p>Trouvez des fichiers spécifiques dans les archives :</p><ol><li>Cliquez sur le bouton <strong>Rechercher</strong> dans la barre d&#39;outils</li><li>Saisissez un motif de nom de fichier</li><li>NueZip recherche dans toutes les entrées de l&#39;archive ouverte</li><li>Les résultats sont affichés avec les chemins complets pour une navigation rapide</li></ol><h2 id="test-de-performance" tabindex="-1">Test de performance <a class="header-anchor" href="#test-de-performance" aria-label="Permalink to &quot;Test de performance&quot;">​</a></h2><p>Testez les performances de compression de votre système :</p><ol><li>Allez dans <strong>Outils → Test de performance</strong></li><li>NueZip exécute des tests de compression en utilisant divers formats et paramètres</li><li>Les résultats affichent la vitesse de compression (Mo/s) et le taux pour chaque format</li><li>Utilisez cela pour comparer les performances selon les différentes méthodes de compression</li></ol><h2 id="archives-multi-volumes-fractionnees" tabindex="-1">Archives multi-volumes (fractionnées) <a class="header-anchor" href="#archives-multi-volumes-fractionnees" aria-label="Permalink to &quot;Archives multi-volumes (fractionnées)&quot;">​</a></h2><p>Créez des archives fractionnées pour les données volumineuses :</p><ol><li>Lors de la compression, activez <strong>Fractionner en volumes</strong></li><li>Choisissez la taille des volumes (par ex., 100 Mo, 650 Mo, 4,7 Go, ou personnalisé)</li><li>NueZip crée des fichiers de parties numérotés (<code>.zip.001</code>, <code>.zip.002</code>, etc.)</li><li>Pour extraire, ouvrez le premier fichier de partie — NueZip charge automatiquement le reste</li></ol><ul><li><strong>Mot de passe</strong> : Fournissez un mot de passe pour les archives chiffrées</li><li><strong>Regrouper dans un dossier</strong> : Crée automatiquement un dossier racine si l&#39;archive n&#39;a pas de répertoire racine unique</li><li><strong>Ouvrir après</strong> : Révèle les fichiers extraits dans Finder à la fin</li><li><strong>Conserver les fichiers incomplets</strong> : Préserve les fichiers extraits avant une erreur (pour récupération partielle)</li><li><strong>Mode de mise à jour</strong> : Choisissez comment gérer les fichiers existants (écraser, ignorer, renommer)</li></ul><h3 id="extraction-par-lot-1" tabindex="-1">Extraction par lot <a class="header-anchor" href="#extraction-par-lot-1" aria-label="Permalink to &quot;Extraction par lot&quot;">​</a></h3><ol><li>Allez dans <strong>Outils → Extraction par lot</strong></li><li>Cliquez sur <strong>Ajouter des fichiers...</strong> pour sélectionner les fichiers d&#39;archive</li><li>Choisissez un dossier de destination</li><li>Activez éventuellement <strong>Supprimer les fichiers source après extraction</strong></li><li>Cliquez sur <strong>Démarrer</strong></li></ol><h2 id="creation-d-archives" tabindex="-1">Création d&#39;archives <a class="header-anchor" href="#creation-d-archives" aria-label="Permalink to &quot;Création d&#39;archives&quot;">​</a></h2><h3 id="compresser-des-fichiers" tabindex="-1">Compresser des fichiers <a class="header-anchor" href="#compresser-des-fichiers" aria-label="Permalink to &quot;Compresser des fichiers&quot;">​</a></h3><ol><li>Cliquez sur le bouton <strong>Compresser</strong> dans la barre d&#39;outils</li><li>Sélectionnez les fichiers à compresser (ou glissez-déposez-les dans la fenêtre)</li><li>Choisissez le <strong>Format d&#39;archive</strong> : ZIP, 7Z, TAR, GZIP, BZIP2</li><li>Configurez la <strong>Méthode de compression</strong> et le niveau</li><li>Définissez l&#39;<strong>Emplacement d&#39;enregistrement</strong> et le nom de l&#39;archive</li><li>Définissez éventuellement un <strong>Mot de passe</strong> pour le chiffrement</li><li>Définissez éventuellement la <strong>Taille de fractionnement</strong> pour les archives multi-volumes</li><li>Cliquez sur <strong>Compresser</strong></li></ol><h3 id="ajouter-des-fichiers-a-une-archive-existante" tabindex="-1">Ajouter des fichiers à une archive existante <a class="header-anchor" href="#ajouter-des-fichiers-a-une-archive-existante" aria-label="Permalink to &quot;Ajouter des fichiers à une archive existante&quot;">​</a></h3><ol><li>Ouvrez une archive existante dans NueZip</li><li>Cliquez sur <strong>Ajouter des fichiers</strong> dans la barre d&#39;outils</li><li>Sélectionnez les fichiers à ajouter</li><li>Cliquez sur <strong>Ajouter</strong></li></ol><h2 id="operations-par-lot-1" tabindex="-1">Opérations par lot <a class="header-anchor" href="#operations-par-lot-1" aria-label="Permalink to &quot;Opérations par lot&quot;">​</a></h2><h3 id="compression-par-lot-1" tabindex="-1">Compression par lot <a class="header-anchor" href="#compression-par-lot-1" aria-label="Permalink to &quot;Compression par lot&quot;">​</a></h3><ol><li>Allez dans <strong>Outils → Compression par lot</strong></li><li>Cliquez sur <strong>Sélectionner des fichiers/dossiers...</strong> pour choisir les éléments</li><li>Chaque élément sélectionné deviendra une archive séparée</li><li>Configurez le <strong>Format</strong> de sortie, l&#39;<strong>Emplacement d&#39;enregistrement</strong> et le préfixe de nommage des fichiers</li><li>Cliquez sur <strong>Démarrer</strong></li></ol><h3 id="conversion-de-format-par-lot" tabindex="-1">Conversion de format par lot <a class="header-anchor" href="#conversion-de-format-par-lot" aria-label="Permalink to &quot;Conversion de format par lot&quot;">​</a></h3><ol><li>Allez dans <strong>Outils → Conversion de format par lot</strong></li><li>Cliquez sur <strong>Ajouter des fichiers...</strong> pour sélectionner les archives sources</li><li>Choisissez le <strong>Format cible</strong></li><li>Activez éventuellement <strong>Supprimer les fichiers source après conversion</strong></li><li>Cliquez sur <strong>Démarrer</strong></li></ol><h3 id="chiffrement-par-lot-1" tabindex="-1">Chiffrement par lot <a class="header-anchor" href="#chiffrement-par-lot-1" aria-label="Permalink to &quot;Chiffrement par lot&quot;">​</a></h3><ol><li>Allez dans <strong>Outils → Chiffrement par lot</strong></li><li>Cliquez sur <strong>Ajouter des fichiers...</strong> pour sélectionner les archives</li><li>Saisissez un <strong>Mot de passe</strong></li><li>Cliquez sur <strong>Chiffrer</strong></li></ol><h2 id="fonctionnalites-avancees" tabindex="-1">Fonctionnalités avancées <a class="header-anchor" href="#fonctionnalites-avancees" aria-label="Permalink to &quot;Fonctionnalités avancées&quot;">​</a></h2><h3 id="reparation-d-archive-1" tabindex="-1">Réparation d&#39;archive <a class="header-anchor" href="#reparation-d-archive-1" aria-label="Permalink to &quot;Réparation d&#39;archive&quot;">​</a></h3><p>Réparez les archives corrompues ou endommagées :</p><ol><li>Sélectionnez l&#39;archive endommagée</li><li>Allez dans <strong>Outils → Réparer l&#39;archive</strong></li><li>NueZip analysera l&#39;en-tête, reconstruira le répertoire et corrigera les blocs de données</li><li>Consultez le résultat de la réparation</li></ol><h3 id="conversion-de-format-1" tabindex="-1">Conversion de format <a class="header-anchor" href="#conversion-de-format-1" aria-label="Permalink to &quot;Conversion de format&quot;">​</a></h3><p>Convertissez des archives entre formats :</p><ol><li>Ouvrez une archive ou sélectionnez un fichier</li><li>Allez dans <strong>Fichier → Convertir le format</strong></li><li>Choisissez le format cible et le niveau de compression</li><li>Supprimez éventuellement le fichier original</li><li>Cliquez sur <strong>Convertir</strong></li></ol><h3 id="gestionnaire-de-mots-de-passe" tabindex="-1">Gestionnaire de mots de passe <a class="header-anchor" href="#gestionnaire-de-mots-de-passe" aria-label="Permalink to &quot;Gestionnaire de mots de passe&quot;">​</a></h3><p>NueZip stocke en toute sécurité les mots de passe d&#39;archives dans votre trousseau local :</p><ol><li>Allez dans <strong>Outils → Gestionnaire de mots de passe</strong></li><li>Affichez tous les mots de passe enregistrés</li><li>Ajoutez, modifiez ou supprimez des entrées</li><li>Les mots de passe sont appliqués automatiquement à l&#39;ouverture des archives chiffrées correspondantes</li></ol><h3 id="test-de-performance-1" tabindex="-1">Test de performance <a class="header-anchor" href="#test-de-performance-1" aria-label="Permalink to &quot;Test de performance&quot;">​</a></h3><p>Testez les performances de compression de votre système :</p><ol><li>Allez dans <strong>Outils → Test de performance</strong></li><li>Sélectionnez un fichier de test (ou utilisez celui par défaut)</li><li>Cliquez sur <strong>Tester</strong></li><li>Consultez les résultats incluant la vitesse de compression/décompression et l&#39;évaluation</li></ol><h3 id="recherche-dans-les-archives-1" tabindex="-1">Recherche dans les archives <a class="header-anchor" href="#recherche-dans-les-archives-1" aria-label="Permalink to &quot;Recherche dans les archives&quot;">​</a></h3><p>Trouvez des fichiers dans les archives :</p><ol><li>Ouvrez une archive</li><li>Appuyez sur <code>Cmd+F</code> ou cliquez sur l&#39;icône de recherche</li><li>Saisissez un nom de fichier, en respectant éventuellement la casse ou le mot entier</li><li>Parcourez les résultats de recherche et cliquez pour naviguer</li></ol><h2 id="raccourcis-clavier" tabindex="-1">Raccourcis clavier <a class="header-anchor" href="#raccourcis-clavier" aria-label="Permalink to &quot;Raccourcis clavier&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Raccourci</th><th>Action</th></tr></thead><tbody><tr><td><code>Cmd+O</code></td><td>Ouvrir une archive</td></tr><tr><td><code>Cmd+N</code></td><td>Nouvelle archive</td></tr><tr><td><code>Cmd+E</code></td><td>Extraire</td></tr><tr><td><code>Cmd+F</code></td><td>Rechercher dans l&#39;archive</td></tr><tr><td><code>Cmd+,</code></td><td>Ouvrir les réglages</td></tr><tr><td><code>Cmd+W</code></td><td>Fermer la fenêtre</td></tr><tr><td><code>Cmd+Q</code></td><td>Quitter l&#39;application</td></tr><tr><td><code>Cmd+↑</code></td><td>Remonter d&#39;un niveau</td></tr><tr><td><code>Cmd+→</code></td><td>Aller vers l&#39;avant</td></tr></tbody></table><h2 id="reglages" tabindex="-1">Réglages <a class="header-anchor" href="#reglages" aria-label="Permalink to &quot;Réglages&quot;">​</a></h2><p>Accédez aux réglages via <strong>NueZip → Réglages</strong> ou appuyez sur <code>Cmd+,</code> :</p><ul><li><strong>Général</strong> : Langue, lancement à la connexion, thème d&#39;apparence</li><li><strong>Compression</strong> : Format par défaut, niveau de compression, taille de fractionnement</li><li><strong>Extraction</strong> : Destination par défaut, comportement de regroupement, résolution des conflits</li><li><strong>Accès aux dossiers</strong> : Gérez les permissions de dossiers et les signets</li><li><strong>Avancé</strong> : Accélération matérielle, nombre de threads, répertoire temporaire</li><li><strong>Confidentialité</strong> : Préférences de collecte de données</li></ul>',85)])])}const m=r(o,[["render",t]]);export{p as __pageData,m as default};
